int addType(final String value) {
    if (value == null) {
        throw new IllegalArgumentException("value cannot be null");
    }
    // Search for an existing type symbol with the same value
    for (int i = 0; i < typeTable.size(); i++) {
        TypeSymbol ts = typeTable.get(i);
        if (value.equals(ts.getValue())) {
            return i;  // Existing type found, return its index
        }
    }
    // No matching type found – create a new one
    TypeSymbol newSymbol = new TypeSymbol(value);
    typeTable.add(newSymbol);
    return typeTable.size() - 1;  // Index of the newly added type symbol
}

