protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour == null || tour.isEmpty() || graph == null){
        return null;
    }

    // Build adjacency map for the edges in the tour
    Map<V, List<E>> adjacency = new HashMap<>();
    for(E e : tour){
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }

    // Pick an arbitrary start edge
    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = graph.getEdgeTarget(startEdge);

    List<V> vertexList = new ArrayList<>();
    List<E> edgeList   = new ArrayList<>();
    Set<E> usedEdges   = new HashSet<>();

    // Initialize path
    vertexList.add(startVertex);
    edgeList.add(startEdge);
    usedEdges.add(startEdge);
    vertexList.add(currentVertex);

    // Build the tour by walking around the cycle
    while(true){
        // If we returned to the start vertex after using all edges, tour is complete
        if(currentVertex.equals(startVertex) && usedEdges.size() == tour.size()){
            break;
        }

        // Find the next unused edge incident to the current vertex
        List<E> incident = adjacency.get(currentVertex);
        if(incident == null){
            return null; // invalid structure
        }

        E nextEdge = null;
        for(E e : incident){
            if(!usedEdges.contains(e)){
                nextEdge = e;
                break;
            }
        }

        if(nextEdge == null){
            return null; // incomplete cycle
        }

        usedEdges.add(nextEdge);
        edgeList.add(nextEdge);

        V u = graph.getEdgeSource(nextEdge);
        V v = graph.getEdgeTarget(nextEdge);
        V nextVertex = u.equals(currentVertex) ? v : u;

        vertexList.add(nextVertex);
        currentVertex = nextVertex;
    }

    // Calculate total weight
    double weight = 0.0;
    for(E e : edgeList){
        weight += graph.getEdgeWeight(e);
    }

    return new DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

