private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // A null or empty set or a single vertex is trivially a clique
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }

    // Convert the set to a list for indexed access
    List<V> list = new ArrayList<>(vertices);

    // Check every unordered pair of vertices
    for (int i = 0; i < size - 1; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V vj = list.get(j);
            // For directed graphs we must consider both directions
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }

    return true;
}

