private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    int length = input.length();
    if (length == 0) {
        return "";
    }
    int start = 0;
    int end = length;
    // Remove surrounding quotes if present
    if (length >= 2) {
        char first = input.charAt(0);
        char last = input.charAt(length - 1);
        if ((first == '\"' && last == '\"') || (first == '\'' && last == '\'')) {
            start = 1;
            end = length - 1;
        }
    }
    StringBuilder sb = new StringBuilder();
    int i = start;
    while (i < end) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < end) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'v':
                    sb.append('\u000B'); // vertical tab
                    break;
                case '0':
                    sb.append('\0');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case 'x':
                    // parse two hex digits
                    if (i + 3 < end) {
                        String hex = input.substring(i + 2, i + 4);
                        try {
                            sb.append((char) Integer.parseInt(hex, 16));
                            i += 3;
                            continue;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('x');
                        }
                    } else {
                        sb.append('\\').append('x');
                    }
                    break;
                case 'u':
                    // parse four hex digits
                    if (i + 5 < end) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            sb.append((char) Integer.parseInt(hex, 16));
                            i += 5;
                            continue;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('u');
                        }
                    } else {
                        sb.append('\\').append('u');
                    }
                    break;
                default:
                    sb.append(next);
                    break;
            }
            i += 2;
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

