private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int startPos = bb.position();
    while (bb.remaining() > 0) {
        int b1 = bb.get() & 0xFF;
        if ((b1 & 0x80) == 0) {
            // 1-byte ASCII
            sb.append((char) b1);
        } else if ((b1 & 0xE0) == 0xC0) {
            // 2-byte sequence
            if (bb.remaining() < 1) break;
            int b2 = bb.get() & 0xFF;
            int codePoint = ((b1 & 0x1F) << 6) | (b2 & 0x3F);
            sb.append((char) codePoint);
        } else if ((b1 & 0xF0) == 0xE0) {
            // 3-byte sequence
            if (bb.remaining() < 2) break;
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            int codePoint = ((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            sb.append((char) codePoint);
        } else if ((b1 & 0xF8) == 0xF0) {
            // 4-byte sequence → surrogate pair
            if (bb.remaining() < 3) break;
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            int b4 = bb.get() & 0xFF;
            int codePoint = ((b1 & 0x07) << 18) | ((b2 & 0x3F) << 12) |
                            ((b3 & 0x3F) << 6) | (b4 & 0x3F);
            codePoint -= 0x10000;
            char high = (char) ((codePoint >> 10) + 0xD800);
            char low = (char) ((codePoint & 0x3FF) + 0xDC00);
            sb.append(high).append(low);
        } else {
            // Invalid UTF-8 start byte; stop decoding
            break;
        }
    }
    int consumed = bb.position() - startPos;
    return i + consumed;
}

