public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segmentsList = new java.util.ArrayList<>();
    if (u == null) {
        return segmentsList;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segmentsList;
    }
    // Remove a leading slash if the path is absolute to avoid an empty leading segment
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // Split on '/' and keep empty segments (including trailing empty segment)
