public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder out = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                throw new Exception("Dangling escape at end of string");
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    out.append('\b');
                    i++;
                    break;
                case 'f':
                    out.append('\f');
                    i++;
                    break;
                case 'n':
                    out.append('\n');
                    i++;
                    break;
                case 'r':
                    out.append('\r');
                    i++;
                    break;
                case 't':
                    out.append('\t');
                    i++;
                    break;
                case '\'':
                    out.append('\'');
                    i++;
                    break;
                case '\"':
                    out.append('\"');
                    i++;
                    break;
                case '\\':
                    out.append('\\');
                    i++;
                    break;
                case 'u':
                    if (i + 5 >= len) {
                        throw new Exception("Invalid unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        out.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape sequence: \\u" + hex);
                    }
                    i += 5;
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int end = j + 1;
                        while (end < len && end - j < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                            end++;
                        }
                        String oct = str.substring(j, end);
                        try {
                            int val = Integer.parseInt(oct, 8);
                            out.append((char) val);
                        } catch (NumberFormatException e) {
                            throw new Exception("Invalid octal escape sequence: \\" + oct);
                        }
                        i = end - 1;
                    } else {
                        throw new Exception("Unrecognized escape sequence: \\" + next);
                    }
            }
        } else {
            out.append(c);
        }
    }
    return out.toString();
}

