public static String stripFilenameExtension(String path){
    if (path == null){
        return null;
    }
    int lastSeparatorIdx = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int lastDotIdx = path.lastIndexOf('.');
    // A valid extension exists when the last dot is after the last separator
    // and there is at least one character following the dot.
    if (lastDotIdx > lastSeparatorIdx && lastDotIdx < path.length() - 1){
        return path.substring(0, lastDotIdx);
    }
    return null;
}

