public String format(LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        // log4j 1.x – use the rendered (formatted) message
        return event.getRenderedMessage();
    } catch (NoSuchMethodError | UnsupportedOperationException e) {
        // Fallback to the message object’s string representation
        Object msg = event.getMessage();
        return msg == null ? "" : msg.toString();
    } catch (Exception e) {
        // In case of any other unexpected error, return an empty string
        return "";
    }
}

