public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    while (true) {
        // Quick checks for even numbers
        if (candidate == 2) {
            return 2;
        }
        if ((candidate & 1) == 0) {
            candidate++;
            continue;
        }
        boolean isPrime = true;
        int sqrt = (int) Math.sqrt(candidate);
        for (int divisor = 3; divisor <= sqrt; divisor += 2) {
            if (candidate % divisor == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate++;
    }
}

