public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Determine the serialized size of the message
    int size = schema.getCachedSize(message);
    if (size < 0) {
        // Use the provided buffer to compute the size
        CodedOutputStream tempCos = CodedOutputStream.newInstance(buffer);
        schema.writeTo(message, tempCos);
        size = buffer.getSize();
    }

    // Write the size prefix (varint) to the output stream
    CodedOutputStream cosOut = CodedOutputStream.newInstance(out);
    cosOut.writeRawVarint32(size);

    // Serialize the message itself to the output stream
    schema.writeTo(message, cosOut);
    cosOut.flush();

    return size;
}

